// No inputs; just call and sanity-check the returned version integer.
unsigned int ver = uv_version();
// Property: version should be non-zero for released libuv builds.
FUZZ_ASSERT(ver != 0u, "uv_version returned 0");
// Validation: simple, no outputs or state changes.

// Returns static string; must be non-NULL and not freed.
const char* vs = uv_version_string();
FUZZ_ASSERT(vs != nullptr, "uv_version_string returned NULL");
// Optionally touch the string to exercise access.
volatile char c0 = vs[0]; (void)c0;
// Validation: static lifetime pointer observed; no ownership taken.

// Enforce single call and only when no active/libuv loops are live.
int already = FUZZ_GET_ATTR_INT_GLOBAL("lib_shutdown");
if (already) { FUZZ_BAIL(); }
int live = FUZZ_GET_ATTR_INT_GLOBAL("loops_live");
if (live != 0) { FUZZ_BAIL(); }
uv_library_shutdown();
FUZZ_SET_ATTR_INT_GLOBAL("lib_shutdown", 1);
// Validation: guarded by global flags; no loops active; called exactly once.

// Must be called before any libuv allocations are in use.
int live = FUZZ_GET_ATTR_INT_GLOBAL("loops_live");
int used = FUZZ_GET_ATTR_INT_GLOBAL("libuv_used");
if (live != 0 || used != 0) { FUZZ_BAIL(); }
// Use the standard C allocators which satisfy the contract and are thread-safe in libc.
int rc = uv_replace_allocator(&::malloc, &::realloc, &::calloc, &::free);
// Return code may be negative on failure; that's acceptable under fuzzing. No further action.
// Validation: Only invoked before libuv is used; allocator callbacks are non-NULL and valid.

// Get or create the process-wide default loop.
uv_loop_t* loop = uv_default_loop();
FUZZ_ASSERT(loop != nullptr, "uv_default_loop returned NULL");
// Mark loop as initialized and as the default; libuv owns its storage.
FUZZ_SET_ATTR_INT(loop, "initialized", 1);
FUZZ_SET_ATTR_INT(loop, "default", 1);
FUZZ_SET_ATTR_INT(loop, "owns_memory", 0);
FUZZ_SET_ATTR_INT(loop, "closed", 0);
// Count it once in global live-loop counter.
if (FUZZ_GET_ATTR_INT(loop, "counted") == 0) {
  FUZZ_SET_ATTR_INT(loop, "counted", 1);
  FUZZ_SET_ATTR_INT_GLOBAL("loops_live", FUZZ_GET_ATTR_INT_GLOBAL("loops_live") + 1);
}
FUZZ_SET_ATTR_INT_GLOBAL("libuv_used", 1);
// Output: loop persists.

// Manually allocate storage of uv_loop_size() bytes and initialize the loop.
size_t sz = uv_loop_size();
if (sz == 0 || sz > (size_t)1<<20) { FUZZ_BAIL(); }
char* raw = new (std::nothrow) char[sz];
if (!raw) { FUZZ_BAIL(); }
uv_loop_t* loop = reinterpret_cast<uv_loop_t*>(raw);
int rc = uv_loop_init(loop);
if (rc != 0) { delete[] raw; FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(loop, "initialized", 1);
FUZZ_SET_ATTR_INT(loop, "default", 0);
FUZZ_SET_ATTR_INT(loop, "owns_memory", 1); // We allocated raw bytes; free on close.
FUZZ_SET_ATTR_INT(loop, "closed", 0);
if (FUZZ_GET_ATTR_INT(loop, "counted") == 0) {
  FUZZ_SET_ATTR_INT(loop, "counted", 1);
  FUZZ_SET_ATTR_INT_GLOBAL("loops_live", FUZZ_GET_ATTR_INT_GLOBAL("loops_live") + 1);
}
FUZZ_SET_ATTR_INT_GLOBAL("libuv_used", 1);
// Output: initialized loop with owned storage.

// Close requires an initialized loop with no active handles/requests.
if (FUZZ_GET_ATTR_INT(loop, "initialized") == 0) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(loop, "closed") != 0) { FUZZ_BAIL(); }
if (uv_loop_alive(loop) != 0) { FUZZ_BAIL(); }
int rc = uv_loop_close(loop);
if (rc != 0) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(loop, "closed", 1);
// Decrement global live-loop counter once.
if (FUZZ_GET_ATTR_INT(loop, "counted") != 0) {
  FUZZ_SET_ATTR_INT(loop, "counted", 0);
  FUZZ_SET_ATTR_INT_GLOBAL("loops_live", FUZZ_GET_ATTR_INT_GLOBAL("loops_live") - 1);
}
// Free memory only if we allocated it for uv_loop_init.
if (FUZZ_GET_ATTR_INT(loop, "owns_memory") != 0) {
  delete[] reinterpret_cast<char*>(loop);
}
// Validation: only closed when no active handles; object is not returned (dropped).

// Deprecated, but still supported: allocate+init by libuv.
uv_loop_t* loop = uv_loop_new();
FUZZ_ASSERT(loop != nullptr, "uv_loop_new returned NULL");
FUZZ_SET_ATTR_INT(loop, "initialized", 1);
FUZZ_SET_ATTR_INT(loop, "from_new", 1);
FUZZ_SET_ATTR_INT(loop, "owns_memory", 0); // freed by uv_loop_delete
FUZZ_SET_ATTR_INT(loop, "closed", 0);
if (FUZZ_GET_ATTR_INT(loop, "counted") == 0) {
  FUZZ_SET_ATTR_INT(loop, "counted", 1);
  FUZZ_SET_ATTR_INT_GLOBAL("loops_live", FUZZ_GET_ATTR_INT_GLOBAL("loops_live") + 1);
}
FUZZ_SET_ATTR_INT_GLOBAL("libuv_used", 1);
// Output: loop persists; to be deleted with uv_loop_delete.

// uv_loop_delete requires a loop created by uv_loop_new and already closed.
if (FUZZ_GET_ATTR_INT(loop, "from_new") == 0) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(loop, "closed") == 0) { FUZZ_BAIL(); }
// Decrement live-loop counter if not yet done (defensive, though close stub handles it).
if (FUZZ_GET_ATTR_INT(loop, "counted") != 0) {
  FUZZ_SET_ATTR_INT(loop, "counted", 0);
  FUZZ_SET_ATTR_INT_GLOBAL("loops_live", FUZZ_GET_ATTR_INT_GLOBAL("loops_live") - 1);
}
uv_loop_delete(loop);
// Validation: ownership handled by libuv; pointer dropped.

// Query size; ensure non-zero and within a plausible bound.
size_t s = uv_loop_size();
FUZZ_ASSERT(s > 0, "uv_loop_size returned 0");
// Validation: informational query only.

// Check alive status; requires a valid loop.
if (FUZZ_GET_ATTR_INT(loop, "initialized") == 0) { FUZZ_BAIL(); }
int alive = uv_loop_alive(loop);
FUZZ_SET_ATTR_INT(loop, "alive", alive);
// Output loop persists.

// Must be called before running the loop. Enforce initialized.
if (FUZZ_GET_ATTR_INT(loop, "initialized") == 0) { FUZZ_BAIL(); }
// Randomly choose a supported option. UV_METRICS_IDLE_TIME takes no varargs.
unsigned int pick = *FUZZ_PARAM(unsigned int) % 2u;
int rc = 0;
if (pick == 0) {
  rc = uv_loop_configure(loop, UV_METRICS_IDLE_TIME);
} else {
  // UV_LOOP_BLOCK_SIGNAL expects an int signum vararg; pick a small number.
  int signum = (int)(*FUZZ_PARAM(unsigned int) % 8u);
  rc = uv_loop_configure(loop, UV_LOOP_BLOCK_SIGNAL, signum);
}
(void)rc; // May be negative on unsupported platforms; acceptable.
// Output loop persists.

// Run the event loop in a random mode; loop must be initialized.
if (FUZZ_GET_ATTR_INT(loop, "initialized") == 0) { FUZZ_BAIL(); }
unsigned int m = *FUZZ_PARAM(unsigned int) % 3u;
uv_run_mode mode = m == 0 ? UV_RUN_DEFAULT : (m == 1 ? UV_RUN_ONCE : UV_RUN_NOWAIT);
int r = uv_run(loop, mode);
// Record whether the loop still has active work.
FUZZ_SET_ATTR_INT(loop, "alive", r != 0);
// Output loop persists.

// Signal the loop to stop at next opportunity; loop must be initialized.
if (FUZZ_GET_ATTR_INT(loop, "initialized") == 0) { FUZZ_BAIL(); }
uv_stop(loop);
// Output loop persists.

// Increment reference count of an initialized handle to keep loop alive.
if (FUZZ_GET_ATTR_INT(handle, "initialized") == 0) { FUZZ_BAIL(); }
uv_ref(handle);
// Output handle persists.

// Decrement reference count of an initialized handle.
if (FUZZ_GET_ATTR_INT(handle, "initialized") == 0) { FUZZ_BAIL(); }
uv_unref(handle);
// Output handle persists.

// Query ref status of an initialized handle.
if (FUZZ_GET_ATTR_INT(handle, "initialized") == 0) { FUZZ_BAIL(); }
int has = uv_has_ref(handle);
FUZZ_SET_ATTR_INT(handle, "has_ref", has);
// Output handle persists.

// Update loop cached time; loop must be initialized and called from loop thread.
if (FUZZ_GET_ATTR_INT(loop, "initialized") == 0) { FUZZ_BAIL(); }
uv_update_time(loop);
// Output loop persists.

// Read loop cached time; loop must be initialized.
if (FUZZ_GET_ATTR_INT(loop, "initialized") == 0) { FUZZ_BAIL(); }
uint64_t now = uv_now(loop);
(void)now;
// Output loop persists.

// Query backend fd/handle; loop must be initialized.
if (FUZZ_GET_ATTR_INT(loop, "initialized") == 0) { FUZZ_BAIL(); }
int fd = uv_backend_fd(loop);
(void)fd; // May be -1 on unsupported platforms.
// Output: loop persists.
// Validation: respects init precondition and tolerates platform-specific return.

// Query backend timeout; loop must be initialized.
if (FUZZ_GET_ATTR_INT(loop, "initialized") == 0) { FUZZ_BAIL(); }
int to = uv_backend_timeout(loop);
(void)to;
// Output: loop persists.
// Validation: simple getter with init check.

// Translate an arbitrary system errno value to libuv error code.
int sys_errno = (int)(*FUZZ_PARAM(int));
int uv_err = uv_translate_sys_error(sys_errno);
(void)uv_err;
// Validation: no strict constraints; any int is acceptable.

// Convert a libuv error code to static string.
int err = (int)(*FUZZ_PARAM(int));
const char* s = uv_strerror(err);
FUZZ_ASSERT(s != nullptr, "uv_strerror returned NULL");
volatile char c = s[0]; (void)c;
// Validation: static string pointer, not freed.

// Write strerror into caller buffer; buflen must be > 0.
int err = (int)(*FUZZ_PARAM(int));
size_t buflen = (size_t)(*FUZZ_PARAM(unsigned int) % 256u) + 1u; // [1,256]
char* buf = new (std::nothrow) char[buflen];
if (!buf) { FUZZ_BAIL(); }
char* out = uv_strerror_r(err, buf, buflen);
FUZZ_ASSERT(out == buf, "uv_strerror_r did not return buf");
volatile char c = buf[0]; (void)c;
delete[] buf;
